import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2025-12-10","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2025-12-10","date":"2025-12-10T00:00:00.000Z","updated":"2025-12-10T00:00:00.000Z","tags":["RGW","账户迁移","对象所有权","ACL","S3兼容性"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-12-10.md","filePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-12-10.md","lastUpdated":1780459816000}'),l={name:"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-12-10.md"};function i(n,e,c,s,h,d){return a(),o("div",null,[...e[0]||(e[0]=[r('<h2 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h2><p>本次 Ceph RGW Refactoring Meeting 于 2025 年 12 月 10 日举行，主要围绕 RGW 账户迁移过程中的对象所有权（object ownership）变更、ACL 处理逻辑以及相关测试覆盖展开讨论。</p><h2 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h2><h3 id="_1-账户迁移测试覆盖-put-object测试" tabindex="-1">1. 账户迁移测试覆盖（Put Object测试） <a class="header-anchor" href="#_1-账户迁移测试覆盖-put-object测试" aria-label="Permalink to &quot;1. 账户迁移测试覆盖（Put Object测试）&quot;">​</a></h3><p>Casey 正在编写一个 shell 脚本，用于自动化执行已文档化的用户到账户（user-to-account）迁移流程。该脚本计划集成到 Teuthology 测试框架中，以提供回归测试能力，并为后续新增测试用例奠定基础。</p><p>Kronel 表示此前在查阅相关脚本时未能找到账户迁移相关内容，Casey 的工作正好填补了这一空白。</p><h3 id="_2-节假日会议安排" tabindex="-1">2. 节假日会议安排 <a class="header-anchor" href="#_2-节假日会议安排" aria-label="Permalink to &quot;2. 节假日会议安排&quot;">​</a></h3><p>Casey 建议在节假日期间取消部分例会，下周的会议照常进行，之后两周暂停。</p><h3 id="_3-bucket-chown-与对象所有权变更-核心议题" tabindex="-1">3. Bucket Chown 与对象所有权变更（核心议题） <a class="header-anchor" href="#_3-bucket-chown-与对象所有权变更-核心议题" aria-label="Permalink to &quot;3. Bucket Chown 与对象所有权变更（核心议题）&quot;">​</a></h3><p>讨论围绕 Casey 提交的第二个 PR 展开，该 PR 涉及在 bucket chown 操作时同步变更 bucket 下所有对象的所有权。</p><p><strong>背景说明：</strong></p><ul><li><code>radosgw-admin bucket chown</code> 命令原本已支持变更 bucket 的所有权，新 PR 进一步将变更范围扩展到 bucket 下的所有对象（包括对象的 ACL）。</li><li>在最初设计账户迁移方案时，出于对生产系统中可能存在数百万对象的性能考量，迁移流程刻意只修改 bucket 所有权，而不修改对象所有权。</li></ul><p><strong>两个 PR 的定位区别：</strong></p><ul><li><code>radosgw-admin bucket chown</code>：面向集群管理员（cluster admin/operator），由管理员主动触发所有权变更。</li><li>Casey 的新 PR：允许 S3 客户端自行修复其 bucket 的所有权问题。</li></ul><p>两者服务于不同的使用场景，均有其价值。</p><h3 id="_4-跨账户访问与-acl-兼容性问题-重要发现" tabindex="-1">4. 跨账户访问与 ACL 兼容性问题（重要发现） <a class="header-anchor" href="#_4-跨账户访问与-acl-兼容性问题-重要发现" aria-label="Permalink to &quot;4. 跨账户访问与 ACL 兼容性问题（重要发现）&quot;">​</a></h3><p>讨论中揭示了一个此前未充分考虑的问题：</p><p><strong>问题描述：</strong></p><p>在账户迁移完成后，bucket 的所有权已变更为 account，但 bucket 下的对象所有权仍归属于原始的旧 UID（user ID）。当账户下新增其他用户（如 STS 用户、临时用户或普通用户）时，这些用户尝试访问带有旧 UID 所有权的对象时，RGW 的 authorization逻辑会将此类请求判定为跨账户（cross-account）请求，从而导致访问被拒绝。</p><p><strong>根本原因：</strong></p><p>RGW 使用旧式 canonical UID 命名规范标记对象所有者，迁移后 bucket 归属于 account，但对象的 owner 字段仍为旧 UID，两者不匹配，触发跨账户策略评估逻辑。</p><p><strong>可能的解决方案：</strong></p><ol><li>使用 <code>bucket chown</code> 命令批量修改所有对象的所有权（但对大规模生产系统代价较高）。</li><li>为相关用户配置显式的 bucket policy，授予访问权限（但目前不确定是否存在适用的 policy配置）。</li><li>利用 main 分支已有的 <strong>S3 Object Ownership</strong> 特性，在迁移前先禁用对象 ACL（object ACLs），再执行迁移——但此方案对 Squid 和 Tentacle 版本无效，且对已有 ACL 的对象行为需进一步验证。</li></ol><p><strong>代码层面的补充说明：</strong></p><p>当前 RGW 代码实现中，即使对象没有显式 ACL，代码也会自动创建一个默认 ACL，将当前用户设为 owner 并进行验证。因此，当 requester 与 owner 一致时，访问始终被允许；问题出现在 requester 与 owner 不一致的跨用户场景。</p><h3 id="_5-aws-行为对比验证" tabindex="-1">5. AWS 行为对比验证 <a class="header-anchor" href="#_5-aws-行为对比验证" aria-label="Permalink to &quot;5. AWS 行为对比验证&quot;">​</a></h3><p>与会者建议通过对比 AWS 的实际行为来验证上述逻辑：</p><ul><li>AWS 本身不存在 UID 与 account ID 分离的概念，bucket 默认归属于创建者的账户。</li><li>需要验证的场景：当 bucket 属于某账户，而 bucket 内的对象由另一个账户上传时，bucket owner 发起的对象访问请求，AWS 是否会将其判定为跨账户请求。</li><li>该场景是 RGW 账户迁移特有的问题，AWS 原生不存在此类迁移需求。</li></ul><h2 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h2><ol><li>Casey 的账户迁移 shell 脚本将集成到 Teuthology，作为回归测试基础。</li><li>Kronel 将验证账户内新增用户访问旧 UID 所有权对象的实际行为，并与 AWS 行为进行对比测试。</li><li>上述测试用例将纳入账户迁移的 QA 测试矩阵中。</li></ol><h2 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h2><table tabindex="0"><thead><tr><th>负责人</th><th>行动项</th></tr></thead><tbody><tr><td>Casey</td><td>完成账户迁移 shell 脚本并提交至 Teuthology</td></tr><tr><td>Kronel</td><td>验证账户内多用户访问旧 UID 对象的行为，对比 AWS 实际表现</td></tr><tr><td>全体</td><td>评估 S3 Object Ownership 特性在迁移流程中的适用性</td></tr></tbody></table><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>本次会议深入探讨了 RGW 账户迁移中对象所有权变更的必要性与复杂性。核心结论是：在多用户账户场景下，仅迁移 bucket 所有权而不迁移对象所有权，可能导致账户内其他用户无法访问已有对象，这一问题需要通过 <code>bucket chown</code>、显式 policy 或禁用 ACL 等方式加以解决，具体方案有待进一步测试验证。</p>',34)])])}const b=t(l,[["render",i]]);export{p as __pageData,b as default};
